corrected_code:
const express = require('express');
const OpenApiValidator = require('express-openapi-validator');
const path = require('path');
const { PerformanceReview } = require('../models/hr');

const app = express();
app.use(express.json());

app.use(
  OpenApiValidator.middleware({
    apiSpec: path.join(__dirname, 'specs', 'hr-management-spec.yaml'),
    validateRequests: true
  })
);

app.get('/api/v1/hr/reviews/:reviewId', async (req, res) => {
  if (!req.user || !req.user.employeeId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const review = await PerformanceReview.findByPk(req.params.reviewId);
  if (!review) {
    return res.status(404).json({ error: 'Review not found' });
  }

  // Allow access only to the subject employee, their direct manager, or HR directors
  const isSubject = review.employeeId === req.user.employeeId;
  const isManager = review.managerEmployeeId === req.user.employeeId;
  const isHrAdmin = req.user.roles && req.user.roles.includes('HR_ADMIN');

  if (!isSubject && !isManager && !isHrAdmin) {
    return res.status(403).json({ error: 'Access denied: not authorized to view this review' });
  }

  res.json({
    reviewId: review.id,
    employeeId: review.employeeId,
    rating: review.rating,
    managerNotes: review.managerNotes,
    promotionRecommendation: review.promotionRecommendation,
    salaryAdjustmentPct: review.salaryAdjustmentPct
  });
});

app.listen(5004);
